51	// agentImportStatus summarizes one agent's importable history for this repo.
52	type agentImportStatus struct {
53		Agent string `json:"agent"`
54		// Sessions is every discovered session, imported or not.
55		Sessions        int `json:"sessions"`
56		UnimportedTurns int `json:"unimported_turns"`
57		ImportedTurns   int `json:"imported_turns"`
58	}
