352	func mirrorRung(deps onboardingRungDeps) onboarding.Rung {
353		return onboarding.Rung{
354			Key:   onboarding.KeyMirror,
355			Title: "Repo mirrored",
356			Check: func(ctx context.Context) onboarding.Check {
357				forge, owner, repo, err := deps.resolveOrigin(ctx)
358				if err != nil {
359					// A resolution failure (git exec error, canceled context) is
360					// not the same fact as "this repo isn't on GitHub".
361					logging.Debug(ctx, "onboarding: origin resolution failed", "error", err)
362					return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire repo mirror list"}
363				}
364				if forge != "gh" {
365					return onboarding.Check{State: onboarding.StateNotApplicable, Detail: "no GitHub origin"}
366				}
367				owner, repo = githubSlug(owner, repo)
368				slug := "github.com/" + owner + "/" + repo
369				if !deps.authed(ctx) {
370					return onboarding.Check{
371						State:  onboarding.StateBlocked,
372						Detail: "needs login",
373						Hint:   "entire auth login",
374					}
375				}
376				probe, err := deps.probeMirror(ctx, owner, repo)
377				if err != nil {
378					return onboarding.Check{State: onboarding.StateUnknown, Hint: "entire repo mirror list"}
379				}
380				if probe.Mirrored && probe.Suspended {
381					// Registered but admin-suspended: it never serves, and
382					// re-creating cannot fix it — recovery is operator-side.
383					// Blocked keeps the checklist honest without re-offering.
384					return onboarding.Check{
385						State:  onboarding.StateBlocked,
386						Detail: "mirror suspended by an admin",
387						Hint:   "entire repo mirror list",
388					}
389				}
390				if probe.Mirrored {
391					return onboarding.Check{State: onboarding.StateDone, Detail: slug}
392				}
393				return onboarding.Check{
394					State:  onboarding.StateMissing,
395					Detail: "commits won't appear in the web UI",
396					Hint:   "entire repo mirror create " + slug,
397				}
398			},
399		}
400	}
