17	// runOnboardingLogin is the auth rung's offer: the same browser-first login
18	// `entire login` runs, with default flags (standard login server, no device
19	// mode unless the environment forces it). w is enable's output writer.
20	func runOnboardingLogin(ctx context.Context, w io.Writer) error {
21		loginServer, err := parseLoginServer(api.DefaultAuthBaseURL)
22		if err != nil {
23			return fmt.Errorf("resolve login server: %w", err)
24		}
25		client := auth.NewClient(loginServer, nil, false)
26		startBrowser := func(ctx context.Context) (browserAuthFlow, error) {
27			return client.StartBrowserAuth(ctx)
28		}
29		return runLoginAuto(ctx, w, w, client, startBrowser, openBrowser, loginFlowFacts{
30			canPrompt:  interactive.CanPromptInteractively(),
31			sshSession: isSSHSession(),
