14	// importScanCache memoizes the import rung's dry-run scan, which reads and
15	// parses every discovered transcript file. Invalidation is exact rather than
16	// TTL-based: the cache key fingerprints the discovered files' identity
17	// (path, mtime, size) plus the local metadata-branch tip, so an appended
18	// transcript or a new checkpoint/import (ref moves) recomputes immediately,
19	// while an unchanged repo pays only the cheap discovery glob on hot paths
20	// like `entire status`. Persistence via the shared jsonFileCache shell.
21	type importScanCache struct {
22		path string
23	}
24	
25	func defaultImportScanCache() importScanCache {
26		return importScanCache{path: filepath.Join(userdirs.Cache(), "onboarding_imports.json")}
27	}
28	
29	// importScanInput is one discovered transcript file's cache-relevant identity.
30	type importScanInput struct {
31		Path    string
32		ModTime time.Time
33		Size    int64
34	}
35	
36	// importScanFingerprint hashes the scan inputs order-independently.
37	func importScanFingerprint(files []importScanInput, metadataTip string) string {
38		lines := make([]string, 0, len(files)+1)
39		for _, f := range files {
40			lines = append(lines, fmt.Sprintf("%s|%d|%d", f.Path, f.ModTime.UnixNano(), f.Size))
41		}
42		sort.Strings(lines)
43		lines = append(lines, "tip|"+metadataTip)
44		h := sha256.New()
45		for _, l := range lines {
46			h.Write([]byte(l))
47			h.Write([]byte{'\n'})
48		}
49		return hex.EncodeToString(h.Sum(nil))
50	}
51	
52	// importScanEntry doubles as the on-disk schema: agentImportStatus's json
53	// tags are part of the cache format.
54	type importScanEntry struct {
55		Fingerprint string              `json:"fingerprint"`
56		Statuses    []agentImportStatus `json:"statuses"`
57	}
58	
59	func (c importScanCache) shell() jsonFileCache[importScanEntry] {
60		return jsonFileCache[importScanEntry](c)
61	}
62	
63	func (c importScanCache) get(repoRoot, fingerprint string) ([]agentImportStatus, bool) {
64		entry, found := c.shell().load()[repoRoot]
65		if !found || entry.Fingerprint != fingerprint {
66			return nil, false
67		}
68		return entry.Statuses, true
69	}
70	
71	func (c importScanCache) put(repoRoot, fingerprint string, statuses []agentImportStatus) {
72		shell := c.shell()
73		entries := shell.load()
74		entries[repoRoot] = importScanEntry{Fingerprint: fingerprint, Statuses: statuses}
75		shell.store(entries)
76	}
