151		return firstResolved(s.readOrder(checkpointID),
152			func(st PersistentStore) (*Metadata, error) {
153				return st.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
154			},
155			sessionNotFound[*Metadata],
156		)
157	}
