input.new_string:
// metadataTip identifies the local checkpoint-metadata state for the
// import-scan fingerprint: any new checkpoint or import moves it. Imports land
// on whichever backend is the configured primary, so both are covered — the
// v1 metadata branch tip plus the per-checkpoint refs the git-refs store
// writes (refs/entire/checkpoints/...), which never move the branch tip. The
// error reports a digest computed without the checkpoint refs; callers must
// not cache under it.
func metadataTip(repo *git.Repository) (string, error) {
	digest, err := checkpointRefsDigest(repo)
	return metadataBranchTip(repo) + "+" + digest, err
}

// metadataBranchTip is the git-branch backend's tip (the v1 metadata branch).
func metadataBranchTip(repo *git.Repository) string {
	ref, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	if err != nil {
		return "none"
	}
	return ref.Hash().String()
}

// checkpointRefsDigest hashes the git-refs backend's per-checkpoint refs
// (name and hash), order-independently. An iteration failure returns the
// digest of whatever was seen plus the error.
func checkpointRefsDigest(repo *git.Repository) (string, error) {
	var lines []string
	iter, err := repo.References()
	if err == nil {
		err = iter.ForEach(func(ref *plumbing.Reference) error {
			if name := ref.Name().String(); strings.HasPrefix(name, checkpoint.CheckpointRefPrefix) {
				lines = append(lines, name+"|"+ref.Hash().String())
			}
			return nil
		})
	}
	sort.Strings(lines)
	h := sha256.New()
	for _, l := range lines {
		h.Write([]byte(l))
		h.Write([]byte{'\n'})
	}
	return hex.EncodeToString(h.Sum(nil)), err
}

// Regression: under a git-refs checkpoint primary, an import writes
// refs/entire/checkpoints/<shard>/<id> and never moves the v1 metadata
// branch. The scan fingerprint's metadata tip must still change, or the
// post-import re-check serves the stale pre-import cache entry — `entire
// enable` printed "Imported 2 turn(s)" directly above "✗ History ... not
// imported".
func TestMetadataTip_MovesWithCheckpointRefs(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "f.txt", "init")
	testutil.GitAdd(t, dir, "f.txt")
	testutil.GitCommit(t, dir, "init")
	repo, err := git.PlainOpen(dir)
	if err != nil {
		t.Fatalf("open repo: %v", err)
	}

	before, err := metadataTip(repo)
	if err != nil {
		t.Fatalf("metadataTip before: %v", err)
	}

	head, err := repo.Head()
	if err != nil {
		t.Fatalf("head: %v", err)
	}
	refName := plumbing.ReferenceName(checkpoint.CheckpointRefPrefix + "3q/01hzxw2e8g0000000000003q3q")
	if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, head.Hash())); err != nil {
		t.Fatalf("set checkpoint ref: %v", err)
	}

	after, err := metadataTip(repo)
	if err != nil {
		t.Fatalf("metadataTip after: %v", err)
	}
	if after == before {
		t.Error("a new per-checkpoint ref (git-refs import) must change the metadata tip")
	}
}

